        rLocalLHS(21,18)+=clhs19*(-clhs0*(DeltaNormalSlave[6](0,0)*clhs10 + DeltaNormalSlave[6](0,0)*clhs3 + DeltaNormalSlave[6](0,0)*clhs5 + DeltaNormalSlave[6](0,1)*clhs6 + DeltaNormalSlave[6](0,2)*clhs7 - clhs13*clhs41 - clhs15*clhs42 - clhs17*clhs43) + clhs43);
