        rLocalLHS(22,20)+=clhs19*(-clhs0*(DeltaNormalSlave[8](0,0)*clhs59 + DeltaNormalSlave[8](0,1)*clhs5 + DeltaNormalSlave[8](0,1)*clhs61 + DeltaNormalSlave[8](0,1)*clhs9 + DeltaNormalSlave[8](0,2)*clhs60 - clhs13*clhs51 - clhs49*clhs63 - clhs50*clhs62) + clhs49);
