            const double clhs34 =     -DeltaDOperator[10](0,0)*clhs12 - DeltaDOperator[10](0,1)*clhs13 - DeltaDOperator[10](0,2)*clhs14 + DeltaMOperator[10](0,0)*clhs8 + DeltaMOperator[10](0,1)*clhs9 + DeltaMOperator[10](0,2)*clhs10 + DeltaMOperator[10](0,3)*clhs11;
