            const double crhs11 =     DOperator(1,2)*DynamicFactor[1];
            const double crhs12 =     DOperator(1,3)*DynamicFactor[1];
            const double crhs13 =     1.0/PenaltyParameter[1];
            const double crhs14 =     LM(1,0)*NormalSlave(1,0) + LM(1,1)*NormalSlave(1,1) + LM(1,2)*NormalSlave(1,2);
            const double crhs15 =     mu[1]*(ScaleFactor*crhs14 - crhs4)/ScaleFactor;
            const double crhs16 =     LM(1,1) - NormalSlave(1,1)*crhs14 + TangentSlave(1,1)*crhs15;
